def _q(a):
    f = lambda x: re.sub(r"“([^”]*[A-Za-z][^”]*)”", lambda m: "`“" + m.group(1).replace("**", "") + "”`", x)
    return [f(x) for x in a] if isinstance(a, list) else f(a)
BN = lambda en, ar: N(en, _q(ar), label=["BIOS note", "ملاحظة BIOS"])
